def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("Number must be between 1 and 3999")

    roman_numerals = [
        (1000, 'M'),
        (900, 'CM'),
        (500, 'D'),
        (400, 'CD'),
        (100, 'C'),
        (90, 'XC'),
        (50, 'L'),
        (40, 'XL'),
        (10, 'X'),
        (9, 'IX'),
        (5, 'V'),
        (4, 'IV'),
        (1, 'I'),
    ]

    result = []
    for value, numeral in roman_numerals:
        while n >= value:
            result.append(numeral)
            n -= value
    return ''.join(result)


def from_roman(s):
    """Convert a Roman numeral string back to an integer."""
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    roman_values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000,
    }

    # Validate that all characters are valid Roman numeral characters
    for ch in s:
        if ch not in roman_values:
            raise ValueError(f"Invalid character: {ch}")

    if len(s) == 0:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Convert to values
    values = [roman_values[ch] for ch in s]

    # Check for invalid subtractive patterns
    # A smaller value before a larger one means subtraction, but only certain pairs are allowed
    allowed_subtractive = {
        ('I', 'V'), ('I', 'X'),
        ('X', 'L'), ('X', 'C'),
        ('C', 'D'), ('C', 'M'),
    }

    i = 0
    while i < len(values):
        if i + 1 < len(values) and values[i] < values[i + 1]:
            # This is a subtractive pair
            if (s[i], s[i + 1]) not in allowed_subtractive:
                raise ValueError(f"Invalid subtractive combination: {s[i]}{s[i+1]}")
            i += 2
        else:
            i += 1

    # Compute the integer value
    total = 0
    i = 0
    while i < len(values):
        if i + 1 < len(values) and values[i] < values[i + 1]:
            total += values[i + 1] - values[i]
            i += 2
        else:
            total += values[i]
            i += 1

    # Verify round-trip: convert back and check it matches
    if total < 1 or total > 3999:
        raise ValueError("Result out of range")

    if to_roman(total) != s:
        raise ValueError(f"Not a well-formed numeral: {s}")

    return total

import pytest
from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman function."""

    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_ten(self):
        assert to_roman(10) == "X"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_forty_nine(self):
        assert to_roman(49) == "XLIX"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_ninety(self):
        assert to_roman(90) == "XC"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_four_hundred(self):
        assert to_roman(400) == "CD"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_nine_hundred(self):
        assert to_roman(900) == "CM"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_four_thousand_nine_hundred_ninety_nine(self):
        assert to_roman(3999) == "MMMCMXCIX"

    # Edge cases at boundaries
    def test_min_boundary(self):
        assert to_roman(1) == "I"

    def test_max_boundary(self):
        assert to_roman(3999) == "MMMCMXCIX"

    # Invalid inputs
    def test_zero_raises(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative_raises(self):
        with pytest.raises(ValueError):
            to_roman(-1)

    def test_above_max_raises(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    def test_float_raises(self):
        with pytest.raises(ValueError):
            to_roman(1.5)

    def test_string_raises(self):
        with pytest.raises(ValueError):
            to_roman("1")

    def test_none_raises(self):
        with pytest.raises(ValueError):
            to_roman(None)

    def test_bool_raises(self):
        with pytest.raises(ValueError):
            to_roman(True)

    def test_list_raises(self):
        with pytest.raises(ValueError):
            to_roman([1])

    # Representative values across the range
    def test_seventeen(self):
        assert to_roman(17) == "XVII"

    def test_twenty_three(self):
        assert to_roman(23) == "XXIII"

    def test_1984(self):
        assert to_roman(1984) == "MCMLXXXIV"

    def test_2024(self):
        assert to_roman(2024) == "MMXXIV"

    def test_3000(self):
        assert to_roman(3000) == "MMM"

    def test_3999_subtractive_pairs(self):
        result = to_roman(3999)
        assert "CM" in result
        assert "XC" in result
        assert "IX" in result


