class TestRoundTrip:
    """Test that from_roman(to_roman(n)) == n for all n in 1..3999."""

    def test_all_values_round_trip(self):
        for n in range(1, 4000):
            assert from_roman(to_roman(n)) == n, f"Failed for {n}"

    def test_sample_values_round_trip(self):
        samples = [1, 4, 9, 49, 99, 499, 999, 1999, 2024, 3999]
        for n in samples:
            assert from_roman(to_roman(n)) == n

